import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict with side, price, qty, seq, cancelled
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def clean_buy_top():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or info['cancelled'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return True
        return False

    def clean_sell_top():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or info['cancelled'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return True
        return False

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and not info['cancelled'] and info['qty'] > 0:
                info['cancelled'] = True
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        seq_counter += 1
        my_seq = seq_counter

        if side == 'buy':
            # match against sells
            while remaining > 0 and clean_sell_top():
                s_price, s_seq, s_oid = sell_heap[0]
                if typ != 'market' and price is not None and s_price > price:
                    break
                info = book[s_oid]
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, s_oid, s_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] <= 0:
                    heapq.heappop(sell_heap)
                # else keep at top for next iteration (still smallest price/seq)
                if info['qty'] <= 0:
                    continue
                else:
                    # remaining incoming might be 0 now, loop condition checks
                    if remaining <= 0:
                        break
                    # info still has qty, but remaining incoming also >0 means
                    # this shouldn't happen since trade_qty = min(...)
                    # if trade_qty == remaining, remaining becomes 0, loop ends
                    # if trade_qty == info['qty'], info qty becomes 0, popped
                    continue
        else:
            # side == 'sell', match against buys
            while remaining > 0 and clean_buy_top():
                negprice, b_seq, b_oid = buy_heap[0]
                b_price = -negprice
                if typ != 'market' and price is not None and b_price < price:
                    break
                info = book[b_oid]
                trade_qty = min(remaining, info['qty'])
                trades.append([b_oid, oid, b_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] <= 0:
                    heapq.heappop(buy_heap)
                if info['qty'] <= 0:
                    continue
                else:
                    if remaining <= 0:
                        break
                    continue

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': my_seq, 'cancelled': False}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, my_seq, oid))
            else:
                heapq.heappush(sell_heap, (price, my_seq, oid))
        # ioc/market: discard remainder, no book entry needed (or could add but qty=0 doesn't matter)

    return trades

